
// 1. ARRAY COM TAREFAS JÁ CADASTRADAS

let tarefas = [
    {
            codigo: 1,
                    titulo: "Preparar apresentação",
                            descricao: "Organizar os slides para o trabalho escolar.",
                                    prioridade: "Alta",
                                            concluida: false
                                                },
                                                    {
                                                            codigo: 2,
                                                                    titulo: "Fazer exercícios",
                                                                            descricao: "Resolver atividades de matemática.",
                                                                                    prioridade: "Média",
                                                                                            concluida: false
                                                                                                },
                                                                                                    {
                                                                                                            codigo: 3,
                                                                                                                    titulo: "Organizar os materiais",
                                                                                                                            descricao: "Separar livros e cadernos.",
                                                                                                                                    prioridade: "Baixa",
                                                                                                                                            concluida: true
                                                                                                                                                },
                                                                                                                                                    {
                                                                                                                                                            codigo: 4,
                                                                                                                                                                    titulo: "Estudar programação",
                                                                                                                                                                            descricao: "Praticar JavaScript e desenvolver projetos.",
                                                                                                                                                                                    prioridade: "Alta",
                                                                                                                                                                                            concluida: false
                                                                                                                                                                                                },
                                                                                                                                                                                                    {
                                                                                                                                                                                                            codigo: 5,
                                                                                                                                                                                                                    titulo: "Ler um capítulo",
                                                                                                                                                                                                                            descricao: "Continuar a leitura do livro.",
                                                                                                                                                                                                                                    prioridade: "Média",
                                                                                                                                                                                                                                            concluida: false
                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                ];

                                                                                                                                                                                                                                                let proximoCodigo = 6;


                                                                                                                                                                                                                                                // 2. GERAR CÓDIGOS AUTOMATICAMENTE

                                                                                                                                                                                                                                                function gerarCodigo() {
                                                                                                                                                                                                                                                    return proximoCodigo++;
                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                    // 3. VALIDAR TAREFA

                                                                                                                                                                                                                                                    function validarTarefa(titulo) {
                                                                                                                                                                                                                                                        if (titulo.trim().length < 3) {
                                                                                                                                                                                                                                                                alert("Digite um título com pelo menos 3 caracteres!");
                                                                                                                                                                                                                                                                        return false;
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                // 4. CADASTRAR TAREFA

                                                                                                                                                                                                                                                                                function cadastrarTarefa(evento) {
                                                                                                                                                                                                                                                                                    evento.preventDefault();

                                                                                                                                                                                                                                                                                        const titulo = document.getElementById("titulo").value;
                                                                                                                                                                                                                                                                                            const descricao = document.getElementById("descricao").value;
                                                                                                                                                                                                                                                                                                const prioridade = document.getElementById("prioridade").value;

                                                                                                                                                                                                                                                                                                    if (!validarTarefa(titulo)) {
                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                    const novaTarefa = {
                                                                                                                                                                                                                                                                                                                            codigo: gerarCodigo(),
                                                                                                                                                                                                                                                                                                                                    titulo: titulo.trim(),
                                                                                                                                                                                                                                                                                                                                            descricao: descricao.trim(),
                                                                                                                                                                                                                                                                                                                                                    prioridade: prioridade,
                                                                                                                                                                                                                                                                                                                                                            concluida: false
                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                    tarefas.push(novaTarefa);

                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("formTarefa").reset();

                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                alert("Tarefa adicionada com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                // 5. LISTAR TAREFAS

                                                                                                                                                                                                                                                                                                                                                                                function listarTarefas(lista = tarefas) {
                                                                                                                                                                                                                                                                                                                                                                                    const area = document.getElementById("listaTarefas");

                                                                                                                                                                                                                                                                                                                                                                                        area.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                            atualizarResumo();

                                                                                                                                                                                                                                                                                                                                                                                                if (lista.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                        area.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                    '<p class="vazio">Nenhuma tarefa encontrada.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                    lista.forEach(function(tarefa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                            const elemento = document.createElement("div");

                                                                                                                                                                                                                                                                                                                                                                                                                                                    elemento.className = tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? "tarefa concluida"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "tarefa";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const titulo = document.createElement("h3");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            titulo.textContent = tarefa.titulo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const codigo = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            codigo.textContent = "Código: " + tarefa.codigo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const descricao = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            descricao.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Descrição: " + (tarefa.descricao || "Sem descrição");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const prioridade = document.createElement("span");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        prioridade.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Prioridade: " + tarefa.prioridade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            prioridade.className = "prioridade " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa.prioridade.toLowerCase().normalize("NFD")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .replace(/[\u0300-\u036f]/g, "");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const status = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status.textContent = tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? "Status: Concluída ✓"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "Status: Pendente";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const acoes = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            acoes.className = "acoes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const concluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            concluir.textContent = tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "Reabrir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "Concluir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            concluir.className = "concluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    concluir.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                concluirTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const alterar = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alterar.textContent = "Alterar prioridade";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alterar.className = "alterar";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alterar.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alterarPrioridade(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const excluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            excluir.textContent = "Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    excluir.className = "excluir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            excluir.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        excluirTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes.append(concluir, alterar, excluir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elemento.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            titulo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        codigo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    descricao,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                prioridade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        area.appendChild(elemento);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 6. ATUALIZAR INDICADORES

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarResumo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const total = tarefas.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const concluidas = tarefas.filter(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return tarefa.concluida;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pendentes = total - concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("total").textContent = total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("pendentes").textContent = pendentes;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("concluidas").textContent = concluidas;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 7. BUSCAR TAREFAS COM FIND

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function buscarTarefa(termo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pesquisa = termo.trim().toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (pesquisa === "") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const resultado = tarefas.find(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return tarefa.titulo.toLowerCase().includes(pesquisa) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String(tarefa.codigo) === pesquisa;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (resultado) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarTarefas([resultado]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas([]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 8. CONCLUIR OU REABRIR TAREFA

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function concluirTarefa(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.concluida = !tarefa.concluida;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 9. ALTERAR PRIORIDADE

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function alterarPrioridade(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!tarefa) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const opcao = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Escolha a prioridade:\n1 - Baixa\n2 - Média\n3 - Alta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const prioridades = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "1": "Baixa",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "2": "Média",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "3": "Alta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (opcao === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (prioridades[opcao]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.prioridade = prioridades[opcao];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Opção inválida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 10. EXCLUIR TAREFA

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function excluirTarefa(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Deseja realmente excluir esta tarefa?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!confirmar) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefas = tarefas.filter(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return tarefa.codigo !== codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 11. EVENTOS

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("formTarefa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener("submit", cadastrarTarefa);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("busca")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("input", function(evento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                buscarTarefa(evento.target.value);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 12. INICIAR SISTEMA

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    